symmetric_tree.optimal:
is_mirror(a, b):
    if a is empty or b is empty: return true only if both are empty
    if a.val != b.val: return false
    return is_mirror(a.left, b.right) and is_mirror(a.right, b.left)   (outer pair, inner pair)
if the root is empty: return true
return is_mirror(root.left, root.right)

balanced_binary_tree.brute:
height(node): 0 if empty, else 1 + max(height(node.left), height(node.right))
if the root is empty: return true
if |height(root.left) - height(root.right)| > 1: return false   (heights recomputed at every level)
return brute_force(root.left) and brute_force(root.right)

validate_binary_search_tree.brute:
all_values(node): every value in the subtree, collected recursively
if the root is empty: return true
for each value in all_values(root.left):   (the same subtree is rescanned by every ancestor)
    if value >= root.val: return false
for each value in all_values(root.right):
    if value <= root.val: return false
return brute_force(root.left) and brute_force(root.right)

validate_binary_search_tree.optimal:
valid(node, low, high):
    if the node is empty: return true
    if node.val <= low or node.val >= high: return false
    return valid(node.left, low, node.val) and valid(node.right, node.val, high)   (tighten the open interval)
return valid(root, -infinity, +infinity)

lowest_common_ancestor_of_a_bst.optimal:
low = min(p.val, q.val), high = max(p.val, q.val)
node = root
while node exists:
    if high < node.val: node = node.left   (both targets are to the left)
    else if low > node.val: node = node.right   (both targets are to the right)
    else: return node   (low <= node.val <= high: they split here)
return empty
